import { LLMTag, ModuleTagArg } from './llm-tags'
import { TagBlock } from './types'

export const getProjectRevisionIdFromTagBlock = (block: TagBlock) => {
	if (
		[
			LLMTag.PAGE,
			LLMTag.EXPO_PAGE,
			LLMTag.COMPONENT,
			LLMTag.FUNCTION,
			LLMTag.FILE
		].includes(block.tag) &&
		typeof block.args?.[ModuleTagArg.REVISION_ID] === 'string'
	) {
		return block.args[ModuleTagArg.REVISION_ID]
	}
	return null
}
